// instr_mem.v -- read-only instruction memory.
//
// A single-cycle CPU needs its instruction available combinationally: the
// same clock cycle that PC updates, that instruction must already be on
// `instr` so the decoders, register file, ALU, etc. can all act on it
// before the *next* clock edge. So this is a plain asynchronous-read ROM,
// word-addressed (RV32I instructions are always 4 bytes, always aligned).
//
// Program contents come from an external hex file, one 32-bit instruction
// per line, generated by scripts/project4_riscv_verify/asm/assembler.py --
// see that file for the tiny RV32I assembler used to build the programs in
// this project. $readmemh keeps the *program* (data) separate from the
// *hardware* (this module), exactly like Task 11's self-checking testbenches
// keep stimulus data in .hex files instead of hard-coding it into Verilog.
module instr_mem #(
    parameter MEM_FILE  = "hello_uart.hex",
    parameter MEM_WORDS = 256              // 256 words = 1KB of program space
)(
    input      [31:0] addr,   // byte address (from pc) -- word-aligned, low 2 bits ignored
    output     [31:0] instr
);

    reg [31:0] rom [0:MEM_WORDS-1];

    initial begin
        $readmemh(MEM_FILE, rom);
    end

    // addr[31:2] selects the word; addr[1:0] is always 00 for a well-formed
    // program (RV32I has no unaligned instruction fetches).
    assign instr = rom[addr[$clog2(MEM_WORDS)+1:2]];

endmodule
